def library_items():
    items = []
    for it in LIB:
        x = dict(it)
        items.append(x)
    for (sid, title, show, date, desc, topics, kw, links) in PODCASTS:
        items.append(dict(id='pod-'+sid[:6].lower(), kind='podcast', title=title, sub=show, date=date, year=int(date[:4]), desc=desc, topics=topics, kw=kw,
                          aud=['Parents','Educators'] if 'Parenting' in topics else ['Educators','Parents','Students'], thumb=('us-velasquez-mic' if sid=='5FpaHdterTLr0j9XxK5TGH' else 'sp-'+sid.lower()), spotify=sid, links=links, href=None))
    for p in PODCASTS_EXTRA:
        x = dict(p); x['kind']='podcast'; x['year']=int(p['date'][:4]); x['kw']=''; x['aud']=['Educators','Parents']; x['href']=None; x['links']=[]
        items.append(x)
    return items

FAQ = [
 ('Consent Is BAE (Before Anything Else)', [
   ('What is consent?', 'Consent means asking permission: “permission for something to happen or agreement to do something.” People practice consent long before it has anything to do with sex, starting when a caretaker teaches a child to say “please.” SafeBAE teaches consent through six pillars: Mutual, Ongoing, Voluntary, Enthusiastic, Revocable, and Sober.', 'https://www.safebae.org/what-is-consent/'),
   ('Can someone give consent if they’re drunk or high?', 'No. This is the key rule from the SafeBAE Peer Educator Training: if someone isn’t sober, they cannot consent to sexual activity. Sexual contact with a person who is under the influence is sexual assault, even if they say yes. If someone is too impaired to drive, they are too impaired to consent.', 'https://www.safebae.org/can-a-drunk-person-give-consent/'),
   ('What is sexual coercion?', 'Coercion is when one person pressures someone to do something by using force, pressure, guilt, or threats. Consent is not possible when there is coercion. Coercion can happen intentionally or by accident, which is why open communication matters: a partner should feel safe saying no without worrying about upsetting you.', 'https://www.safebae.org/what-is-sexual-coercion/'),
 ]),
 ('Understanding Sexual Violence', [
   ('What is rape culture?', 'Rape culture is a collection of values, attitudes, beliefs, and behaviors that trivializes or normalizes sexual violence: victim blaming, slut-shaming, sexual objectification, minimizing the impact of rape, and refusing to acknowledge the harm it causes. It starts with rape jokes, catcalling, “locker room talk,” and not believing survivors.', 'https://www.safebae.org/what-is-rape-culture/'),
   ('What is the difference between sexual harassment, sexual assault, and rape?', 'All three are forms of sexual violence and sit on a continuum of harm. Sexual harassment is unwelcome sexual advances, requests, or verbal, physical, or online conduct of a sexual nature. Sexual assault is sexual contact or behavior that happens without explicit consent. Rape is legally defined differently across states, often as penetration without consent.', 'https://www.safebae.org/sexual-harassment-vs-sexual-assault-vs-rape/'),
   ('Why don’t survivors report sexual assault?', 'If a survivor doesn’t report to the police, it does not mean the violence didn’t happen. Survivors cite emotional pain and trauma, shame and stigma, fear of not being believed, fear that nothing will be done (fewer than 2% of reports lead to a conviction), fear of punishment or retaliation, and not realizing at first that what happened was abuse.', 'myths-facts.html#survivors-report'),
   ('Can boys and men be victims of sexual violence?', 'Yes. All genders are vulnerable to sexual violence, and all genders are capable of harming others. One out of 10 rape victims is male, over half of male victims of completed or attempted rape were first victimized before age 18, and women can and do commit sexual violence against men.', 'https://www.safebae.org/can-men-be-victims-of-sexual-violence/'),
 ]),
 ('Healthy Relationships & Boundaries', [
   ('What are the signs of a healthy relationship?', 'In a healthy relationship, partners respect each other and stay independent people. Healthy signs include open communication, mutual respect, trust, shared decisions, feeling safe, healthy boundaries, respectful disagreements, enjoying time apart, and inspiring each other. Look at the whole relationship, not one good or bad moment.', 'https://www.safebae.org/signs-of-a-healthy-relationship/'),
   ('What are the signs of an unhealthy or abusive relationship?', 'Warning signs include guilt trips, isolating you from family and friends, unreasonable jealousy, constant put-downs, “if you love me, you will…”, threats, intimidation, manipulation, gaslighting, and love-bombing. Abuse can be physical, sexual, psychological, emotional, or financial. One out of three teens will be in an abusive relationship.', 'https://www.safebae.org/signs-of-an-abusive-relationship/'),
 ]),
 ('Online Safety & Sending Nudes', [
   ('What are the risks of sending nudes?', 'SafeBAE doesn’t judge anyone for sending nudes; the goal is informed decisions. Risks include someone sharing your image without permission, using it for revenge or blackmail (sextortion), being pressured into sending, and criminal consequences, because it is illegal to share or receive sexual images of anyone under 18.', 'https://www.safebae.org/risks-of-sending-nudes/'),
 ]),
 ('Taking Action & Your Rights', [
   ('What is bystander intervention?', 'Bystander intervention is the idea that anyone can step in to help prevent violence, harassment, or abuse, and it doesn’t have to be confrontational. SafeBAE teaches the four D’s: Direct, Distract, Delegate, and Delay. A bystander is present in about 30% of rapes, threats of rape, or unwanted sexual contact.', 'https://www.safebae.org/what-is-bystander-intervention/'),
   ('What is Title IX and what are my rights at school?', 'Title IX is the federal civil rights law that bars sex discrimination, including sexual harassment and assault, at any school that receives federal funding. You have the right to report, to supportive measures such as a schedule change, and to a prompt, fair investigation. Supportive measures are available even if you don’t want an investigation.', 'title-ix.html'),
   ('How do I report sexual assault? What are my options?', 'Whether or not someone reports doesn’t change the validity of what happened. Options include telling a trusted person, talking confidentially with a counselor or doctor, telling school staff (many are mandatory reporters), filing a Title IX complaint, reporting anonymously, or reporting to law enforcement. Survivors decide how, when, and where to seek help.', 'https://www.safebae.org/how-to-report-sexual-assault/'),
 ]),
 ('Support & Healing', [
   ('How do I support a friend who has been sexually assaulted?', 'Start by believing them. The first person a survivor talks to can shape their healing. Listen without pushing for details, don’t minimize their experience, make space for their emotions, don’t pressure them to report, review options together, and keep checking in.', 'https://www.safebae.org/how-to-support-a-survivor/'),
   ('How do survivors heal after sexual assault?', 'Healing is long, nonlinear, and personal, and there is no right or wrong way to do it. Many survivors find strength in connection with peers, support groups, or professionals, and in practices that help them reconnect with their bodies and feelings.', 'https://www.safebae.org/healing-after-sexual-assault/'),
 ]),
]
